; M7700 disassembly — 23710-2L904 (1998 Nissan Maxima VQ30DE ECU)
; ROM base $1000, end $FFFF, 15665 instructions decoded
; CPU: Mitsubishi M37702 (M7700 family), bank 0 only
; Assumptions: DPR=0, DT=0, bank 0, m=x=0 at vectors
;
; === ROM LAYOUT ===
;   $1000-$10FF  Sensor pointer table (Consult register → RAM address map)
;   $1100-$115F  Active test table, configuration bytes
;   $1160-$11DF  Active test descriptor table (0A command)
;   $1200-$12BF  Linearization / lookup tables
;   $12C0-$12FF  RPM axis (32 × 16-bit breakpoints)
;   $1300-$13FF  FUEL_MAP (16×16)
;   $1400-$14FF  TIMING_MAP (16×16)
;   $1500-$2BFF  Additional maps, tables, calibration data
;   $2C00-$3421  Zero-fill (unused ROM space)
;   $3422-$3D74  Early code, padding
;   $3D75        VEC_RESET — power-on initialization
;   $4476-$4583  Exception/vector handlers (BRK, NMI, timers)
;   $4BC2-$4E4D  Main task scheduler (10ms heartbeat via UART0 TX ISR)
;   $4E61-$4EF4  I/O refresh, timer/port reload
;   $4EF5-$543E  Consult protocol handler (UART1 RX ISR)
;   $551F        ADC sensor read subroutine
;   $5600-$7FBF  Engine control subroutines (RPM, load, fuel, timing, idle, knock, O2, injectors)
;   $8102-$9EDA  Secondary tasks (DTC, A/T, battery, speed, diagnostics, active tests)
;   $A4DB-$CF5A  Fuel trim learn, EEPROM, OBD, misfire monitor
;   $D128-$E915  Battery/power, EGR, evap, O2 heater, Consult TX
;   $E915        Interrupt acknowledge subroutine
;   $E95F-$EA5A  Active test parameter tables (per-test register maps)
;   $FEE0-$FFCF  MAP_FEE0 (late map data)
;   $FFD4-$FFFF  Interrupt vector table
;
; === RAM MAP (key addresses) ===
;   $0035-$0036  UART1 data/status registers (M37702 I/O)
;   $00B9        Timer A2 event flags (CAS dispatch)
;   $00D0        DPR shadow / scratch
;   $00F0-$00F1  UART1 TX/RX control
;   $0200-$02FF  I/O shadow registers (timer config, port states)
;   $0700-$070F  Misc engine flags, port output image
;   $0710        Port output register copy
;   $071B        Consult rx_state (protocol state machine)
;   $071C-$071D  Consult cmd_flags / arg state
;   $0737        Consult rx_byte (last received)
;   $0738        Consult tx_byte (response/echo)
;   $0739        Consult tx_index
;   $073A        Consult cmd_byte (stored command)
;   $073B        Consult arg_count
;   $073C        Active test count
;   $073D        Active test register ID
;   $073E+       Consult tx_buffer
;   $076A        Active test mask
;   $076F+       Active test value buffer
;   $07A0-$07AB  Consult stream register list
;   $07AC-$07BB  Active test bit fields
;   $07BC        Active test control flags
;   $07C2        UART1 status snapshot
;   $0810-$0822  Active test output values
;   $08D2+       ROM read / register argument buffer
;   $0900        Engine state word
;   $0902        Scratch / RPM work
;   $0907        throttle_pos
;   $092A        Misc scheduler flags
;   $092C        Scheduler state (bit 6 = busy)
;   $092E        Task dispatch flags (bit2=adc, bit4=engine, bit5=secondary, bit6=bg)
;   $0934-$0935  Fan LH/RH state
;   $0944        Ignition active flags
;   $0958        Timer output shadow
;   $096A        Tick counter (0-9, round-robin scheduler)
;   $096B        Overflow count (missed scheduler ticks)
;   $0980        RPM_raw
;   $0981        RPM_idx (lookup index into RPM axis)
;   $0982        RPM_hi
;   $0983        RPM_period
;   $0986        Coolant sample timer
;   $0988-$098A  Coolant delta history
;   $098B        coolant_temp
;   $098C        Scratch (arg count work)
;   $0991        A/D snapshot (last reading)
;   $0994        battery_v
;   $09AE        load_raw
;   $09B0        load_idx
;   $09B4        load_hi
;   $09F0        TPS raw
;   $09F4        Battery voltage raw
;   $0A0C        Pending ignition coil fire mask
;   $0A0D        iac_duty
;   $0A12        airflow
;   $0A14        ign_dwell
;   $0A65        knock_level
;   $0AF6-$0AFD  Fan parameter work area
;   $0B07        Fan enable flags
;   $0B18        O2 sensor LH
;   $0B36        O2 sensor RH
;   $0BA7        o2_sensor (generic)
;   $0BC5        idle_val
;   $0BCB        iac_pos
;   $0C1F        vehicle_speed
;   $0C48        Active test scratch
;   $0C96-$0C97  A/D watchdog
;   $0DAC-$0DAD  A/F alpha LH/RH
;   $0DD0        IAC / injector control flags
;   $0DDF-$0DE1  Timer/counter work area
;   $0E0D        iac_duty (output)
;   $0E51-$0E57  Active test state
;   $0E78-$0E7A  Active test counters
;   $0F69-$0F79  Freeze-frame / EEPROM area
;

VEC_AD           .equ $447C    ; [FFD4]
VEC_UART1_TX     .equ $4EF5    ; [FFD6]
VEC_UART1_RX     .equ $4EF5    ; [FFD8]
VEC_UART0_TX     .equ $4BC2    ; [FFDA]
VEC_UART0_RX     .equ $447C    ; [FFDC]
VEC_TB2          .equ $44B6    ; [FFDE]
VEC_TB1          .equ $447C    ; [FFE0]
VEC_TB0          .equ $447C    ; [FFE2]
VEC_TA4          .equ $4540    ; [FFE4]
VEC_TA3          .equ $4495    ; [FFE6]
VEC_TA2          .equ $46C0    ; [FFE8]
VEC_TA1          .equ $447C    ; [FFEA]
VEC_TA0          .equ $447C    ; [FFEC]
VEC_INT2         .equ $4797    ; [FFEE]
VEC_INT1         .equ $447C    ; [FFF0]
VEC_INT0         .equ $447C    ; [FFF2]
VEC_NMI          .equ $473F    ; [FFF4]
VEC_WDT          .equ $447C    ; [FFF6]
VEC_DBC          .equ $447B    ; [FFF8]
VEC_BRK          .equ $447C    ; [FFFA]
VEC_ZERO_DIV     .equ $4476    ; [FFFC]
VEC_RESET        .equ $3D75    ; [FFFE]

