; $FFFF = unsupported register (ECU sends stop-ack).
; reg $00/$01 = RPM hi/lo, $04/$05 = MAF, $08 = coolant, $09/$0A = O2,
; $0B = speed, $0C = battery, $0D = TPS, $0E/$0F = timing, $11 = IAT,
; $14/$15 = injector LH, $16 = ign timing, $1A/$1B = A/F alpha, etc.
;
