; === RESET VECTOR — ECU power-on initialization ===
; Sets up the M37702 CPU: DPR, stack, I/O ports, timers, UARTs.
; Clears engine RAM ($0700-$08F9, $0E80-$0F79), then falls into the main init.
;
VEC_RESET:
    3D75  C2 FB                   CLP #$FB         ; clear all status flags except I
    3D77  A9 00 00                LDA #$0000
    3D7A  5B                      TCD              ; DPR = 0 (direct page at $0000)
    3D7B  8D 00 09                STA $0900        ; clear engine state word
    3D7E  E2 24                   SEP #$24         ; set m flag (8-bit accumulator)
    3D80  89 C2 00                LDT #$00         ; data bank = 0
    3D83  64 D8 24                LDM $24,#$D8     ; $D8 = I/O control: enable timers
    3D86  64 2F 00                LDM $00,#$2F     ; port 2 direction
    3D89  64 30 05                LDM $05,#$30     ; port 3 mode
    3D8C  64 31 33                LDM $33,#$31     ; port 3 direction
    3D8F  3C 06 12 01 05          BBC $1206,#1,reset_uart0_mode
    3D94  64 35 04                LDM $04,#$35     ; UART1 mode (variant A)
    3D97  80 03                   BRA reset_uart_common

reset_uart0_mode:
    3D99  64 35 05                LDM $05,#$35     ; UART1 mode (variant B — this car)

reset_uart_common:
    3D9C  64 34 04                LDM $04,#$34     ; UART0 mode
    3D9F  64 2E FC                LDM $FC,#$2E     ; port 2 function select
    3DA2  A2 FF 0F                LDX #$0FFF       ; stack at top of internal RAM
    3DA5  9A                      TXS
    3DA6  86 D0                   STX $D0
    3DA8  A9 00                   LDA #$00
    3DAA  A2 F9 08                LDX #$08F9

reset_clear_ram1:                                  ; clear $0700-$08F9
    3DAD  95 00                   STA $00,X
    3DAF  CA                      DEX
    3DB0  E0 FF 06                CPX #$06FF
    3DB3  D0 F8                   BNE reset_clear_ram1
    3DB5  A2 79 0F                LDX #$0F79

