; === Exception handlers ===
VEC_ZERO_DIV:                                     ; divide-by-zero: return $FFFF (saturate)
    4476  D8                      CLM
    4477  A9 FF FF                LDA #$FFFF
    447A  40                      RTI

VEC_DBC:                                          ; debug break: do nothing
    447B  40                      RTI

VEC_BRK:                                          ; BRK / unused vector: soft reset the scheduler
    447C  C2 38                   CLP #$38
    447E  A9 00 00                LDA #$0000
    4481  5B                      TCD              ; DPR = 0
    4482  8D 03 03                STA $0303
    4485  F8                      SEM
    4486  89 C2 00                LDT #$00         ; data bank = 0
    4489  A2 24 00                LDX #$0024
    448C  DA                      PHX
    448D  28                      PLP              ; restore m=x=0
    448E  04 D8 08                SEB $08,#$D8     ; re-enable timers
    4491  5C 7C 44 00             JMP $00447C      ; loop back (catch-all idle)

; === TIMER A3 INTERRUPT — ignition coil dwell timing ===
VEC_TA3:
    4495  C2 38                   CLP #$38
    4497  EB 0F                   PSH #$0F
    4499  F8                      SEM
    449A  3C 44 09 01 0F          BBC $0944,#1,ta3_done  ; ignition active?
    449F  AD 0C 0A                LDA $0A0C        ; pending coil fire mask
    44A2  F0 0A                   BEQ ta3_done
    44A4  0D 98 0A                ORA $0A98        ; accumulate fire events
    44A7  8D 98 0A                STA $0A98
    44AA  22 02 C5 00             JSL $00C502      ; coil_fire — trigger ignition coil

