; === TIMER A2 INTERRUPT — crankshaft position sensor (CAS) capture ===
; Multiplexed: the M37702 timer A2 can trigger on multiple events.
; $B9 flags track which sub-event fired; each is dispatched and cleared.
;
VEC_TA2:
    46C0  C2 38                   CLP #$38
    46C2  EB 0F                   PSH #$0F
    46C4  F8                      SEM
    46C5  34 B9 01 07             BBC $B9,#1,ta2_check_bit2  ; event 1: CAS reference pulse?
    46C9  64 B9 FE                LDM $FE,#$B9     ; clear bit 1
    46CC  D8                      CLM
    46CD  FB 0F                   PUL #$0F
    46CF  40                      RTI              ; handled inline

ta2_check_bit2:
    46D0  34 B9 02 0A             BBC $B9,#2,ta2_check_bit4  ; event 2: CAS 1° signal?
    46D4  64 B9 FD                LDM $FD,#$B9     ; clear bit 2
    46D7  D8                      CLM
    46D8  FB 0F                   PUL #$0F
    46DA  5C 1B 47 00             JMP $00471B      ; → crank_1deg_handler

ta2_check_bit4:
    46DE  34 B9 04 0A             BBC $B9,#4,ta2_check_bit8  ; event 4: CAS 120° signal?
    46E2  64 B9 FB                LDM $FB,#$B9     ; clear bit 4
    46E5  D8                      CLM
    46E6  FB 0F                   PUL #$0F
    46E8  5C 11 47 00             JMP $004711      ; → crank_120deg_handler

ta2_check_bit8:
    46EC  34 B9 08 07             BBC $B9,#8,ta2_other  ; event 8: overflow/timeout
    46F0  64 B9 F7                LDM $F7,#$B9     ; clear bit 8
    46F3  D8                      CLM
    46F4  FB 0F                   PUL #$0F
    46F6  40                      RTI

ta2_other:
    46F7  34 B9 10 07             BBC $B9,#16,ta2_bit32
    46FB  64 B9 EF                LDM $EF,#$B9     ; clear bit 16
    46FE  D8                      CLM
    46FF  FB 0F                   PUL #$0F
    4701  40                      RTI

ta2_bit32:
    4702  34 B9 20 07             BBC $B9,#32,ta2_spurious
    4706  64 B9 DF                LDM $DF,#$B9     ; clear bit 32
    4709  D8                      CLM
    470A  FB 0F                   PUL #$0F
    470C  40                      RTI

ta2_spurious:
    470D  D8                      CLM
    470E  FB 0F                   PUL #$0F
    4710  40                      RTI

; --- crank_120deg_handler: count 120° crank events (saturate at $FFFF) ---
crank_120deg_handler:
    4711  F8                      SEM
    4712  EE 00 07                INC $0700        ; crank_120_count++
    4715  D0 03                   BNE crank_120_done
    4717  CE 00 07                DEC $0700        ; overflow → clamp at $FFFF

crank_120_done:
    471A  40                      RTI

