; === UART0 TX INTERRUPT — main task scheduler / heartbeat tick ===
; This ISR fires on UART0 transmit-complete, repurposed as the ~10ms heartbeat.
; It dispatches engine control tasks on a round-robin schedule (10 slots):
;   Slot 0,5: ADC reads (analog sensors)
;   Slot 1,6: engine control suite (fuel, ignition, idle, knock, O2...)
;   Slot 3,8: secondary tasks (diagnostics, DTC, A/T comm, misc)
;   Slot 2,4,7,9: background tasks (cooling, EGR, canister, speed...)
; Task flags in $092E bits: 2=adc, 4=engine, 5=secondary, 6=background
;
VEC_UART0_TX:
    4BC2  C2 38                   CLP #$38
    4BC4  EB 0F                   PSH #$0F
    4BC6  F8                      SEM
    4BC7  A2 FF FF                LDX #$FFFF
    4BCA  86 D0                   STX $D0          ; set DPR to bank 0
    4BCC  AD A0 01                LDA $01A0        ; read A/D result register
    4BCF  CD 91 09                CMP $0991        ; changed since last tick?
    4BD2  F0 0C                   BEQ sched_save_ad
    4BD4  9C 97 0C FF             LDM $FF0C,#$97   ; AD watchdog: reset timeout
    4BD8  42 AD 91 09             LDB $0991
    4BDC  42 8D 96 0C             STB $0C96        ; save previous AD value

sched_save_ad:
    4BE0  8D 91 09                STA $0991        ; save current AD value
; --- Coolant temp rate-of-change tracking (for warmup enrichment) ---
    4BE3  AE 86 09                LDX $0986        ; coolant_sample_timer
    4BE6  E8                      INX
    4BE7  E0 59 01                CPX #$0159       ; every 345 ticks (~3.5 sec)
    4BEA  90 1F                   BCC sched_store_timer
    4BEC  AD 88 09                LDA $0988        ; shift coolant delta history
    4BEF  8D 89 09                STA $0989
    4BF2  AD 8A 09                LDA $098A
    4BF5  8D 88 09                STA $0988
    4BF8  AD 91 09                LDA $0991
    4BFB  38                      SEC
    4BFC  ED 8B 09                SBC $098B        ; delta = current - last sample
    4BFF  8D 8A 09                STA $098A
    4C02  AD 91 09                LDA $0991
    4C05  8D 8B 09                STA $098B        ; update last sample
    4C08  A2 00 00                LDX #$0000       ; reset timer

sched_store_timer:
    4C0B  8E 86 09                STX $0986
; --- External module communication (A/T, traction control) ---
    4C0E  3C E2 02 01 0A          BBC $02E2,#1,sched_check_ext
    4C13  1C E2 02 01             CLB $0102,#$E2
    4C17  22 B2 73 01             JSL $0173B2      ; ext_comm_send
    4C1B  80 11                   BRA sched_check_reentry

sched_check_ext:
    4C1D  AD E0 02                LDA $02E0        ; ext_comm_busy?
    4C20  D0 0C                   BNE sched_check_reentry
    4C22  AD E2 02                LDA $02E2
    4C25  8D E0 02                STA $02E0
    4C28  F0 04                   BEQ sched_check_reentry
    4C2A  22 72 72 01             JSL $017272      ; ext_comm_start

; --- Re-entry guard: if scheduler is already running, just count and exit ---
sched_check_reentry:
    4C2E  3C 2C 09 40 07          BBC $092C,#64,sched_enter  ; scheduler_busy flag
    4C33  EE 6B 09                INC $096B        ; overflow_count++
    4C36  D8                      CLM
    4C37  FB 0F                   PUL #$0F
    4C39  40                      RTI

; --- Round-robin tick: choose which task group runs this tick ---
sched_enter:
    4C3A  0C 2C 09 40             SEB $4009,#$2C   ; set scheduler_busy
    4C3E  A2 20 00                LDX #$0020       ; set m=x=0 (16-bit mode)
    4C41  DA                      PHX
    4C42  28                      PLP
    4C43  AD 6A 09                LDA $096A        ; tick_counter (0-9)
    4C46  3A                      INA              ; tick_counter++
    4C47  C9 0A                   CMP #$0A         ; mod 10
    4C49  90 02                   BCC sched_store_tick
    4C4B  A9 00                   LDA #$00

sched_store_tick:
    4C4D  8D 6A 09                STA $096A
    4C50  AA                      TAX
    4C51  4A                      LSR A            ; odd tick?
    4C52  90 04                   BCC sched_check_slot
    4C54  0C 2E 09 04             SEB $0409,#$2E   ; odd → set adc_task flag

sched_check_slot:
    4C58  8A                      TXA
    4C59  C9 01                   CMP #$01         ; slot 1 → engine control
    4C5B  F0 12                   BEQ sched_set_engine
    4C5D  C9 06                   CMP #$06         ; slot 6 → engine control
    4C5F  F0 0E                   BEQ sched_set_engine
    4C61  C9 03                   CMP #$03         ; slot 3 → secondary tasks
    4C63  F0 04                   BEQ sched_set_secondary
    4C65  C9 08                   CMP #$08         ; slot 8 → secondary tasks
    4C67  D0 0A                   BNE sched_dispatch  ; others → background only

sched_set_secondary:
    4C69  0C 2E 09 20             SEB $2009,#$2E   ; set secondary_task flag
    4C6D  80 04                   BRA sched_dispatch

sched_set_engine:
    4C6F  0C 2E 09 10             SEB $1009,#$2E   ; set engine_task flag

; === Task dispatcher: execute pending task groups by priority ===
sched_dispatch:
    4C73  78                      SEI
    4C74  3C 2E 09 04 0B          BBC $092E,#4,sched_try_engine  ; adc_task flag?
    4C79  1C 2E 09 04             CLB $0409,#$2E   ; clear flag
    4C7D  58                      CLI
    4C7E  22 1F 55 00             JSL $00551F      ; adc_read — sample analog sensors
    4C82  80 EF                   BRA sched_dispatch

; --- Engine control task group (slots 1, 6) ---
sched_try_engine:
    4C84  3C 2E 09 10 4F          BBC $092E,#16,sched_try_bg  ; engine_task flag?
    4C89  1C 2E 09 10             CLB $1009,#$2E   ; clear flag
    4C8D  58                      CLI
    4C8E  22 00 56 00             JSL $005600      ; rpm_calc — compute RPM from crank signal
    4C92  22 24 56 00             JSL $005624      ; load_calc — compute engine load
    4C96  22 18 6F 01             JSL $016F18      ; airflow_calc
    4C9A  22 A5 56 00             JSL $0056A5      ; coolant_process — temp compensation
    4C9E  22 9E F1 00             JSL $00F19E      ; warmup_enrich
    4CA2  22 30 57 00             JSL $005730      ; fuel_map_lookup
    4CA6  22 92 5B 00             JSL $005B92      ; ignition_timing — base timing + corrections
    4CAA  22 79 5C 00             JSL $005C79      ; knock_control
    4CAE  22 BD 5C 00             JSL $005CBD      ; knock_retard_decay
    4CB2  22 1B 5F 00             JSL $005F1B      ; idle_control — ISC valve + target RPM
    4CB6  22 4C 64 00             JSL $00644C      ; o2_feedback_lh — LH closed-loop fuel trim
    4CBA  22 BA 66 00             JSL $0066BA      ; o2_feedback_rh — RH closed-loop fuel trim
    4CBE  22 3A 68 00             JSL $00683A      ; injector_lh — compute LH pulse width
    4CC2  22 F3 68 00             JSL $0068F3      ; injector_rh — compute RH pulse width
    4CC6  22 20 6A 00             JSL $006A20      ; injector_output_lh — write to timer
    4CCA  22 C9 6A 00             JSL $006AC9      ; injector_output_rh — write to timer
    4CCE  22 C7 7C 00             JSL $007CC7      ; ign_dwell_calc — dwell time for coils
    4CD2  22 BF 7F 00             JSL $007FBF      ; ign_output — write to ignition timers
    4CD6  80 9B                   BRA sched_dispatch

; --- Background task group (slots 0,2,4,5,7,9) ---
sched_try_bg:
    4CD8  2C 2E 09 40 04          BBS $092E,#64,sched_bg_run  ; background_task flag?
    4CDD  5C 6F 4D 00             JMP sched_try_secondary

sched_bg_run:
    4CE1  1C 2E 09 40             CLB $4009,#$2E   ; clear flag
    4CE5  58                      CLI
    4CE6  22 0F 6C 00             JSL $006C0F      ; egr_control
    4CEA  22 73 6C 00             JSL $006C73      ; canister_purge
    4CEE  22 A7 6F 01             JSL $016FA7      ; speed_calc
    4CF2  22 05 70 01             JSL $017005      ; cruise_control
; --- Cooling fan control: LH and RH bank fan relays ---
    4CF6  AD 07 0B                LDA $0B07        ; fan_enable_flags
    4CF9  2D 0D 16                AND $160D        ; mask for LH fan
    4CFC  F0 2A                   BEQ sched_bg_rh_fan
    4CFE  0C 3C 09 20             SEB $2009,#$3C   ; set fan_active_lh
    4D02  AD 34 09                LDA $0934
    4D05  42 AD 4D 09             LDB $094D
    4D09  A0 44 0B                LDY #$0B44
    4D0C  A2 08 0B                LDX #$0B08
    4D0F  22 4E 4E 00             JSL $004E4E      ; fan_speed_lookup
    4D13  A9 09                   LDA #$09
    4D15  22 65 6D 00             JSL $006D65      ; output_pwm (fan LH)
    4D19  8D 34 09                STA $0934
    4D1C  42 8D 4D 09             STB $094D
    4D20  22 14 7A 01             JSL $017A14      ; fan_lh_output
    4D24  22 A8 DB 00             JSL $00DBA8      ; fan_lh_diag

sched_bg_rh_fan:
    4D28  1C 3C 09 20             CLB $2009,#$3C   ; clear fan_active_lh
    4D2C  AD 07 0B                LDA $0B07
    4D2F  2D 0E 16                AND $160E        ; mask for RH fan
    4D32  F0 2A                   BEQ sched_bg_misc
    4D34  AD 35 09                LDA $0935
    4D37  42 AD 4E 09             LDB $094E
    4D3B  A0 5A 0B                LDY #$0B5A
    4D3E  A2 26 0B                LDX #$0B26
    4D41  22 4E 4E 00             JSL $004E4E      ; fan_speed_lookup
    4D45  A9 03                   LDA #$03
    4D47  22 65 6D 00             JSL $006D65      ; output_pwm (fan RH)
    4D4B  8D 35 09                STA $0935
    4D4E  42 8D 4E 09             STB $094E
    4D52  22 89 79 01             JSL $017989      ; fan_rh_output
    4D56  22 7E DB 00             JSL $00DB7E      ; fan_rh_diag
    4D5A  22 02 81 00             JSL $008102      ; ac_relay_control

sched_bg_misc:
    4D5E  3C 07 0B 09 08          BBC $0B07,#9,sched_bg_done
    4D63  22 55 E3 00             JSL $00E355      ; consult_tx_prepare — build Consult response frame
    4D67  22 99 E3 00             JSL $00E399      ; consult_tx_send — transmit response frame

sched_bg_done:
    4D6B  5C 73 4C 00             JMP sched_dispatch

; --- Secondary task group (slots 3, 8) ---
sched_try_secondary:
    4D6F  2C 2E 09 20 04          BBS $092E,#32,sched_sec_run  ; secondary_task flag?
    4D74  5C 3A 4E 00             JMP sched_done

sched_sec_run:
    4D78  1C 2E 09 20             CLB $2009,#$2E   ; clear flag
    4D7C  58                      CLI
    4D7D  22 26 84 00             JSL $008426      ; dtc_check — scan for active DTCs
    4D81  22 40 84 00             JSL $008440      ; dtc_update — update DTC status flags
    4D85  22 9D 86 00             JSL $00869D      ; dtc_mil_control — check engine light logic
    4D89  22 9F 87 00             JSL $00879F      ; at_comm — A/T communication
    4D8D  22 88 94 00             JSL $009488      ; vehicle_speed_output
    4D91  22 28 D1 00             JSL $00D128      ; battery_monitor
    4D95  22 E8 D1 00             JSL $00D1E8      ; power_supply_check
    4D99  22 37 D2 00             JSL $00D237      ; alt_regulator — alternator control
    4D9D  22 79 D2 00             JSL $00D279      ; fuel_pump_relay
    4DA1  22 CB D2 00             JSL $00D2CB      ; starter_inhibit
    4DA5  22 5A CF 00             JSL $00CF5A      ; immobilizer_check
    4DA9  22 26 D9 00             JSL $00D926      ; oxygen_heater_control
    4DAD  22 D6 D4 00             JSL $00D4D6      ; catalyst_monitor
    4DB1  22 34 DD 00             JSL $00DD34      ; evap_leak_check
    4DB5  22 FE 97 00             JSL $0097FE      ; tps_adaptation — throttle position learn
    4DB9  22 6A 98 00             JSL $00986A      ; idle_learn
    4DBD  22 1B 99 00             JSL $00991B      ; idle_switch_check
    4DC1  22 6A D4 00             JSL $00D46A      ; ac_request
    4DC5  22 0E 95 00             JSL $00950E      ; neutral_safety
    4DC9  22 BD CB 00             JSL $00CBBD      ; misfire_monitor
; DTC $55 = no malfunction: skip certain diag routines when no faults
    4DCD  AD 04 02                LDA $0204        ; dtc_current
    4DD0  C9 55                   CMP #$55
    4DD2  F0 04                   BEQ sched_sec_skip_dtc_diag
    4DD4  22 F5 C7 00             JSL $00C7F5      ; dtc_extended_diag

sched_sec_skip_dtc_diag:
    4DD8  3C 06 12 01 06          BBC $1206,#1,sched_sec_uart0
    4DDD  22 91 7B 01             JSL $017B91      ; consult_alt_comm (UART1 mode)
    4DE1  80 08                   BRA sched_sec_post_comm

sched_sec_uart0:
    4DE3  22 6A 99 00             JSL $00996A      ; consult_rx_process — process Consult commands
    4DE7  22 A6 9E 00             JSL $009EA6      ; consult_tx_response — build/send response frames

sched_sec_post_comm:
    4DEB  AD 04 02                LDA $0204
    4DEE  C9 55                   CMP #$55
    4DF0  F0 04                   BEQ sched_sec_skip_diag2
    4DF2  22 52 CC 00             JSL $00CC52      ; dtc_freeze_frame

sched_sec_skip_diag2:
    4DF6  22 DA 9E 00             JSL $009EDA      ; consult_active_test_exec
    4DFA  22 DB A4 00             JSL $00A4DB      ; fuel_trim_learn_lh
    4DFE  22 B9 A9 00             JSL $00A9B9      ; fuel_trim_learn_rh
    4E02  22 EF A9 00             JSL $00A9EF      ; fuel_trim_store
    4E06  22 54 AC 00             JSL $00AC54      ; eeprom_update
    4E0A  22 00 BD 00             JSL $00BD00      ; obd_mode6_calc
    4E0E  22 C9 C0 00             JSL $00C0C9      ; obd_readiness
    4E12  22 6D BC 00             JSL $00BC6D      ; obd_pid_support
    4E16  22 66 E0 00             JSL $00E066      ; power_balance_test
    4E1A  22 DD E3 00             JSL $00E3DD      ; consult_stream_update
    4E1E  22 A2 E7 00             JSL $00E7A2      ; watchdog_refresh
    4E22  22 FC 81 00             JSL $0081FC      ; safety_relay_check
    4E26  22 F6 E2 00             JSL $00E2F6      ; consult_active_apply
    4E2A  22 48 E8 00             JSL $00E848      ; timer_housekeeping
    4E2E  22 68 F4 00             JSL $00F468      ; rom_checksum_verify
    4E32  22 61 4E 00             JSL $004E61      ; io_refresh — reload timer/port registers
    4E36  5C 73 4C 00             JMP sched_dispatch

; --- Scheduler exit: drain overflow ticks, then clear busy flag ---
sched_done:
    4E3A  AD 6B 09                LDA $096B        ; overflow_count (ticks missed during exec)
    4E3D  F0 07                   BEQ sched_exit
    4E3F  CE 6B 09                DEC $096B
    4E42  5C 3A 4C 00             JMP sched_enter  ; re-enter to catch up

sched_exit:
    4E46  1C 2C 09 40             CLB $4009,#$2C   ; clear scheduler_busy
    4E4A  D8                      CLM
    4E4B  FB 0F                   PUL #$0F
    4E4D  40                      RTI

; --- fan_speed_lookup: store fan parameters for PWM output ---
fan_speed_lookup:
    4E4E  8D FA 0A                STA $0AFA
    4E51  42 8D FC 0A             STB $0AFC
    4E55  8C F8 0A                STY $0AF8
    4E58  8E F6 0A                STX $0AF6
    4E5B  B5 0C                   LDA $0C,X
    4E5D  8D FD 0A                STA $0AFD
    4E60  6B                      RTL

; --- io_refresh: reload all timer/port configuration registers ---
io_refresh:
    4E61  78                      SEI
    4E62  64 10 00                LDM $00,#$10
    4E65  64 11 07                LDM $07,#$11
    4E68  64 13 80                LDM $80,#$13
    4E6B  64 14 FC                LDM $FC,#$14
    4E6E  64 16 1B                LDM $1B,#$16
    4E71  64 17 00                LDM $00,#$17
    4E74  9C 21 02 00             LDM $0002,#$21
    4E78  9C 23 02 00             LDM $0002,#$23
    4E7C  9C 25 02 FF             LDM $FF02,#$25
    4E80  9C 27 02 FF             LDM $FF02,#$27
    4E84  9C 29 02 FF             LDM $FF02,#$29
    4E88  9C 2B 02 FF             LDM $FF02,#$2B
    4E8C  9C 2D 02 F8             LDM $F802,#$2D
    4E90  9C 2F 02 F2             LDM $F202,#$2F
    4E94  AD 10 07                LDA $0710
    4E97  8D 35 02                STA $0235
    4E9A  EA                      NOP
    4E9B  EA                      NOP
    4E9C  EA                      NOP
    4E9D  EA                      NOP
    4E9E  EA                      NOP
    4E9F  EA                      NOP
    4EA0  EA                      NOP
    4EA1  EA                      NOP
    4EA2  EA                      NOP
    4EA3  9C 31 02 01             LDM $0102,#$31
    4EA7  AD 58 09                LDA $0958
    4EAA  85 0B                   STA $0B
    4EAC  AD 60 09                LDA $0960
    4EAF  8D 1D 02                STA $021D
    4EB2  AD 0F 07                LDA $070F
    4EB5  8D 1F 02                STA $021F
    4EB8  3C 51 09 40 19          BBC $0951,#64,L_4ED6
    4EBD  A9 55                   LDA #$55
    4EBF  2C 2B 09 02 02          BBS $092B,#2,L_4EC6
    4EC4  A9 AA                   LDA #$AA

L_4EC6:
    4EC6  85 0C                   STA $0C
    4EC8  8D 15 02                STA $0215
    4ECB  8D 17 02                STA $0217
    4ECE  8D 19 02                STA $0219
    4ED1  8D 1B 02                STA $021B
    4ED4  58                      CLI
    4ED5  6B                      RTL

L_4ED6:
    4ED6  AD 59 09                LDA $0959
    4ED9  85 0C                   STA $0C
    4EDB  AD 5C 09                LDA $095C
    4EDE  8D 15 02                STA $0215
    4EE1  AD 5D 09                LDA $095D
    4EE4  8D 17 02                STA $0217
    4EE7  AD 5E 09                LDA $095E
    4EEA  8D 19 02                STA $0219
    4EED  AD 5F 09                LDA $095F
    4EF0  8D 1B 02                STA $021B
    4EF3  58                      CLI
    4EF4  6B                      RTL

; === CONSULT UART1 RX INTERRUPT — protocol state machine ===
; Receives bytes from the Consult diagnostic port (UART1).
; State tracked in $071B (rx_state) and $071C (cmd_flags):
;   $071B bits: 0=saw_FF_1, 1=saw_FF_2, 2=got_init_ED, 3=has_arg,
;               4=cmd_parsed, 5=streaming, 7=first_FF_seen
;   $071C bits: 0=init_done, 1=stop_req, 3=reg_read(5A), 4=sending,
;               5=tx_ready, 6=rom_read(C9), 7=active_arg
; RX data byte in B register ($36 = UART1 data), status in A ($35).
;
VEC_UART1_RX:
    4EF5  C2 38                   CLP #$38
    4EF7  EB 0F                   PSH #$0F
    4EF9  F8                      SEM
    4EFA  3C 06 12 01 04          BBC $1206,#1,consult_rx_main
    4EFF  5C 08 7B 01             JMP $017B08

consult_rx_main:
    4F03  A5 35                   LDA $35          ; UART1 status register
    4F05  42 A5 36                LDB $36          ; UART1 data register (rx byte)
    4F08  8D C2 07                STA $07C2        ; save uart_status
    4F0B  42 8D 37 07             STB $0737        ; save rx_byte
    4F0F  A5 F0                   LDA $F0          ; UART1 control reg
    4F11  29 07                   AND #$07         ; TX enabled?
    4F13  F0 4C                   BEQ consult_rx_check_input
    4F15  3C C2 07 02 47          BBC $07C2,#2,consult_rx_check_input  ; no TX-empty flag
    4F1A  2C 1C 07 10 10          BBS $071C,#16,consult_tx_next_byte
    4F1F  64 F0 00                LDM $00,#$F0     ; disable TX
    4F22  1C 1C 07 20             CLB $2007,#$1C   ; clear tx_ready
    4F26  22 C7 54 00             JSL $0054C7       ; flush_uart
    4F2A  AD 38 07                LDA $0738        ; echo/response byte
    4F2D  80 30                   BRA consult_tx_store

consult_tx_next_byte:
    4F2F  42 AD 39 07             LDB $0739        ; tx_index
    4F33  A2 3E 07                LDX #$073E       ; tx_buffer base
    4F36  EE 39 07                INC $0739
    4F39  42 D5 01                CMPB $01,X        ; cmp tx_index >= tx_length?
    4F3C  90 12                   BCC consult_tx_send
    4F3E  F0 10                   BEQ consult_tx_send
    4F40  2C 1C 07 20 03          BBS $071C,#32,consult_tx_disable
    4F45  64 F0 00                LDM $00,#$F0     ; disable TX interrupt

consult_tx_disable:
    4F48  1C 1C 07 10             CLB $1007,#$1C   ; clear sending flag
    4F4C  9C 39 07 00             LDM $0007,#$39   ; reset tx_index

consult_tx_send:
    4F50  D8                      CLM
    4F51  42 29 FF 00             ANDB #$00FF
    4F55  18                      CLC
    4F56  42 69 3E 07             ADCB #$073E      ; tx_buffer[tx_index]
    4F5A  42 AA                   TBX
    4F5C  F8                      SEM
    4F5D  B5 00                   LDA $00,X

consult_tx_store:
    4F5F  85 32                   STA $32          ; write to UART1 TX data

; --- Consult RX: check for incoming data and dispatch state machine ---
consult_rx_check_input:
    4F61  A5 F1                   LDA $F1          ; UART1 RX control
    4F63  29 07                   AND #$07         ; RX enabled?
    4F65  F0 39                   BEQ consult_rx_done
    4F67  AD C2 07                LDA $07C2        ; uart_status
    4F6A  29 88                   AND #$88         ; rx_full | overrun?
    4F6C  F0 32                   BEQ consult_rx_done
    4F6E  42 AD 37 07             LDB $0737        ; B = received byte
    4F72  3C 1B 07 01 2D          BBC $071B,#1,consult_rx_state1  ; not in state "saw_FF_1"?
; --- State 0: waiting for first $FF of init sequence (FF FF ED) ---
    4F77  2C C2 07 80 20          BBS $07C2,#128,consult_rx_clear_ff ; framing error → reset
    4F7C  42 C9 FF                CMPB #$FF        ; is it $FF?
    4F7F  D0 1B                   BNE consult_rx_clear_ff  ; no → clear state
    4F81  2C 1B 07 80 0E          BBS $071B,#128,consult_rx_second_ff ; already saw first FF?
    4F86  0C 1B 07 80             SEB $8007,#$1B   ; set first_FF_seen

consult_rx_set_ff1:
    4F8A  0C 1B 07 01             SEB $0107,#$1B   ; set saw_FF_1
    4F8E  1C 1B 07 02             CLB $0207,#$1B   ; clear saw_FF_2
    4F92  80 0C                   BRA consult_rx_done

consult_rx_second_ff:
    4F94  1C 1B 07 01             CLB $0107,#$1B   ; clear saw_FF_1
    4F98  0C 1B 07 02             SEB $0207,#$1B   ; set saw_FF_2 (two FFs received)

consult_rx_clear_ff:
    4F9C  1C 1B 07 80             CLB $8007,#$1B   ; clear first_FF_seen

consult_rx_done:
    4FA0  5C 37 54 00             JMP $005437       ; → consult_rx_exit

; --- State 1: after two FFs, waiting for ECU ID byte ($ED) ---
consult_rx_state1:
    4FA4  3C 1B 07 02 16          BBC $071B,#2,consult_rx_state2  ; not in saw_FF_2?
    4FA9  2C C2 07 80 DC          BBS $07C2,#128,consult_rx_set_ff1  ; framing error → back to FF_1
    4FAE  42 C9 ED                CMPB #$ED        ; ECU ID = $ED (this car's ID)
    4FB1  D0 D7                   BNE consult_rx_set_ff1  ; wrong ID → restart
    4FB3  1C 1B 07 02             CLB $0207,#$1B   ; clear saw_FF_2
    4FB7  0C 1B 07 04             SEB $0407,#$1B   ; set got_init_ED → init complete
    4FBB  5C 17 54 00             JMP consult_echo_reply  ; echo ~ED = $12

; --- State 2+: init done, dispatch command bytes ---
consult_rx_state2:
    4FBF  2C 1B 07 04 04          BBS $071B,#4,consult_rx_cmd  ; got_init? → parse command
    4FC4  5C 42 53 00             JMP consult_streaming  ; else streaming mode

; --- Command dispatch: first byte after init sequence ---
consult_rx_cmd:
    4FC8  2C C2 07 80 6B          BBS $07C2,#128,consult_cmd_reject  ; framing error
    4FCD  3C 1B 07 08 04          BBC $071B,#8,consult_rx_parse_cmd  ; no pending arg? parse
    4FD2  5C 9D 50 00             JMP consult_rx_arg  ; has_arg set → read argument byte

; --- Parse command byte ---
consult_rx_parse_cmd:
    4FD6  42 C9 FF                CMPB #$FF        ; $FF = init/re-init
    4FD9  D0 13                   BNE consult_check_stop

consult_cmd_init:
    4FDB  3C 1B 07 80 06          BBC $071B,#128,consult_cmd_init_first_ff
    4FE0  0C 1C 07 01             SEB $0107,#$1C   ; init_done
    4FE4  80 11                   BRA consult_cmd_flush

consult_cmd_init_first_ff:
    4FE6  0C 1B 07 80             SEB $8007,#$1B   ; first_FF_seen
    4FEA  5C 17 54 00             JMP consult_echo_reply

consult_check_stop:
    4FEE  42 C9 30                CMPB #$30        ; $30 = STOP
    4FF1  D0 0A                   BNE consult_check_romread

consult_cmd_stop:
    4FF3  0C 1C 07 02             SEB $0207,#$1C   ; stop_req

consult_cmd_flush:
    4FF7  22 C7 54 00             JSL $0054C7       ; flush_uart
    4FFB  80 23                   BRA consult_cmd_done

consult_check_romread:
    4FFD  42 C9 C9                CMPB #$C9        ; $C9 = ROM read (2 arg bytes follow)
    5000  D0 06                   BNE consult_check_regread
    5002  0C 1C 07 40             SEB $4007,#$1C   ; rom_read flag
    5006  80 14                   BRA consult_set_has_arg

consult_check_regread:
    5008  42 C9 5A                CMPB #$5A        ; $5A = register read (1 arg byte follows)
    500B  D0 06                   BNE consult_check_active
    500D  0C 1C 07 08             SEB $0807,#$1C   ; reg_read flag
    5011  80 09                   BRA consult_set_has_arg

consult_check_active:
    5013  42 C9 0A                CMPB #$0A        ; $0A = active test (2 arg bytes follow)
    5016  D0 0C                   BNE consult_check_others
    5018  1C 1C 07 48             CLB $4807,#$1C   ; clear rom_read + reg_read

consult_set_has_arg:
    501C  0C 1B 07 08             SEB $0807,#$1B   ; has_arg → next byte(s) are arguments

consult_cmd_done:
    5020  5C 13 54 00             JMP consult_clear_first_ff

; --- Remaining commands: no argument bytes ---
consult_check_others:
    5024  42 C9 51                CMPB #$51        ; $51 = 'Q' → read DTCs
    5027  F0 13                   BEQ consult_cmd_dtc_read
    5029  42 C9 D1                CMPB #$D1        ; $D1 = DTC clear
    502C  F0 61                   BEQ consult_cmd_store_and_ack
    502E  42 C9 C1                CMPB #$C1        ; $C1 = DTC clear (alt)
    5031  F0 5C                   BEQ consult_cmd_store_and_ack
    5033  42 C9 D0                CMPB #$D0        ; $D0 = self-diag result request
    5036  F0 57                   BEQ consult_cmd_store_and_ack

consult_cmd_reject:
    5038  5C A9 53 00             JMP consult_send_stop_ack  ; unknown cmd → send STOP ack

; --- DTC read command ($51 = 'Q'): clear active test outputs first ---
consult_cmd_dtc_read:
    503C  D8                      CLM
    503D  9C 10 08 00 00          LDM $0000,#$0810  ; clear active test outputs $0810-$0820
    5042  9C 12 08 00 00          LDM $0000,#$0812
    5047  9C 14 08 00 00          LDM $0000,#$0814
    504C  9C 16 08 00 00          LDM $0000,#$0816
    5051  9C 18 08 00 00          LDM $0000,#$0818
    5056  9C 1A 08 00 00          LDM $0000,#$081A
    505B  9C 1C 08 00 00          LDM $0000,#$081C
    5060  9C 1E 08 00 00          LDM $0000,#$081E
    5065  9C 20 08 00 00          LDM $0000,#$0820
    506A  9C 51 0E 00 00          LDM $0000,#$0E51  ; clear active test state $0E51-$0E57
    506F  9C 53 0E 00 00          LDM $0000,#$0E53
    5074  9C 55 0E 00 00          LDM $0000,#$0E55
    5079  9C 57 0E 00 00          LDM $0000,#$0E57
    507E  F8                      SEM
    507F  9C 22 08 00             LDM $0008,#$22    ; reset active test counter
    5083  9C 78 0E 00             LDM $000E,#$78
    5087  9C 79 0E 00             LDM $000E,#$79
    508B  9C 7A 0E 00             LDM $000E,#$7A

; --- Store command byte and advance state to "parsed" ---
consult_cmd_store_and_ack:
    508F  42 8D 3A 07             STB $073A        ; save cmd_byte for response phase
    5093  1C 1B 07 04             CLB $0407,#$1B   ; clear got_init_ED
    5097  0C 1B 07 10             SEB $1007,#$1B   ; set cmd_parsed
    509B  80 83                   BRA consult_cmd_done

; --- Argument byte handler: dispatches based on which command set the flags ---
consult_rx_arg:
    509D  3C 1C 07 40 30          BBC $071C,#64,consult_arg_regread  ; rom_read flag?
; ROM read ($C9): collect 2-byte address into buffer at $08D2+
    50A2  AD 3B 07                LDA $073B        ; arg_count
    50A5  D8                      CLM
    50A6  29 FF 00                AND #$00FF
    50A9  18                      CLC
    50AA  69 D2 08                ADC #$08D2       ; rom_arg_buf base
    50AD  AA                      TAX
    50AE  F8                      SEM
    50AF  42 95 00                STB $00,X        ; store arg byte
    50B2  EE 3B 07                INC $073B        ; arg_count++
    50B5  2C 1D 07 01 08          BBS $071D,#1,consult_rom_addr_complete
    50BA  0C 1D 07 01             SEB $0107,#$1D   ; first byte received
    50BE  5C AF 51 00             JMP consult_arg_echo

consult_rom_addr_complete:
    50C2  1C 1D 07 01             CLB $0107,#$1D   ; both bytes received
    50C6  CA                      DEX              ; point to high byte
    50C7  D8                      CLM
    50C8  B5 00                   LDA $00,X        ; load 16-bit ROM address
    50CA  89 49 08 00             RLA #$0008       ; swap bytes (big-endian → little-endian)
    50CE  AA                      TAX
    50CF  F8                      SEM
    50D0  80 37                   BRA consult_rom_read_go

; Register read ($5A): arg byte is register number, look up in pointer table at $1000
consult_arg_regread:
    50D2  3C 1C 07 08 36          BBC $071C,#8,consult_arg_active  ; reg_read flag?
    50D7  42 C9 62                CMPB #$62        ; max register number
    50DA  90 04                   BCC consult_reg_lookup

consult_reg_invalid:
    50DC  5C A9 53 00             JMP consult_send_stop_ack

consult_reg_lookup:
    50E0  42 0A                   ASL B            ; reg * 2 (16-bit pointers)
    50E2  42 A8                   TBY
    50E4  98                      TYA
    50E5  D8                      CLM
    50E6  29 FF 00                AND #$00FF
    50E9  18                      CLC
    50EA  69 00 10                ADC #$1000       ; sensor_ptr_table[$1000 + reg*2]
    50ED  AA                      TAX
    50EE  B5 00                   LDA $00,X        ; load RAM address for this register
    50F0  C9 FF FF                CMP #$FFFF       ; $FFFF = unsupported register
    50F3  F8                      SEM
    50F4  F0 E6                   BEQ consult_reg_invalid
    50F6  AD 3B 07                LDA $073B        ; store reg ID into request buffer
    50F9  D8                      CLM
    50FA  29 FF 00                AND #$00FF
    50FD  18                      CLC
    50FE  69 D2 08                ADC #$08D2
    5101  AA                      TAX
    5102  F8                      SEM
    5103  42 95 00                STB $00,X        ; buf[arg_count] = register
    5106  EE 3B 07                INC $073B        ; arg_count++

consult_rom_read_go:
    5109  5C A7 51 00             JMP consult_arg_finish

; Active test ($0A): arg byte is test register + value
consult_arg_active:
    510D  2C 1C 07 80 79          BBS $071C,#128,consult_active_value  ; waiting for value byte?
; Active test first arg: test register ID ($08-$FF, $80+ = with-value)
    5112  42 C9 08                CMPB #$08        ; minimum test register
    5115  90 52                   BCC consult_active_direct  ; < 8 → direct output test
    5117  38                      SEC
    5118  42 E9 80                SBCB #$80        ; subtract $80 → index into test table
    511B  90 BF                   BCC consult_reg_invalid  ; underflow → invalid
    511D  42 C9 2E                CMPB #$2E        ; max test table entry
    5120  B0 BA                   BCS consult_reg_invalid
    5122  42 0A                   ASL B            ; * 2 for 16-bit table entries
    5124  D8                      CLM
    5125  42 29 FF 00             ANDB #$00FF
    5129  42 69 60 11             ADCB #$1160      ; active_test_table[$1160 + (reg-$80)*2]
    512D  42 AA                   TBX
    512F  B5 00                   LDA $00,X        ; load test descriptor
    5131  C9 FF FF                CMP #$FFFF       ; $FFFF = unsupported test
    5134  F8                      SEM
    5135  F0 A5                   BEQ consult_reg_invalid
    5137  42 B5 01                LDB $01,X
    513A  42 48                   PHB
    513C  89 28                   XAB
    513E  4A                      LSR A
    513F  4A                      LSR A
    5140  4A                      LSR A
    5141  4A                      LSR A
    5142  C9 06                   CMP #$06
    5144  90 02                   BCC L_5148
    5146  A9 05                   LDA #$05

L_5148:
    5148  D8                      CLM
    5149  29 07 00                AND #$0007
    514C  A8                      TAY
    514D  F8                      SEM
    514E  42 19 AC 07             ORB $07AC,Y
    5152  42 99 AC 07             STB $07AC,Y
    5156  42 68                   PLB
    5158  42 29 7F                ANDB #$7F
