; --- Streaming mode: commands received while stream is active ---
; Entered when got_init is not set but we're in cmd_parsed or streaming state.
consult_streaming:
    5342  2C 1B 07 10 04          BBS $071B,#16,consult_stream_cmd  ; cmd_parsed?
    5347  5C EE 53 00             JMP consult_stream_active

; Stream: check for control commands while building command list
consult_stream_cmd:
    534B  2C C2 07 80 59          BBS $07C2,#128,consult_send_stop_ack  ; framing error → stop
    5350  42 C9 FF                CMPB #$FF        ; re-init?
    5353  D0 04                   BNE consult_stream_check_stop
    5355  5C DB 4F 00             JMP consult_cmd_init

consult_stream_check_stop:
    5359  42 C9 30                CMPB #$30        ; STOP?
    535C  D0 04                   BNE consult_stream_check_go
    535E  5C F3 4F 00             JMP consult_cmd_stop

; $F0 = GO — start streaming the requested registers
consult_stream_check_go:
    5362  42 C9 F0                CMPB #$F0        ; GO command
    5365  D0 27                   BNE consult_stream_check_more
    5367  1C 1B 07 90             CLB $9007,#$1B   ; clear first_FF + cmd_parsed
    536B  0C 1B 07 20             SEB $2007,#$1B   ; set streaming
    536F  AE AC 07                LDX $07AC        ; copy active_test_bits → stream snapshot
    5372  8E B7 07                STX $07B7
    5375  AE AE 07                LDX $07AE
    5378  8E B9 07                STX $07B9
    537B  AE B0 07                LDX $07B0
    537E  8E BB 07                STX $07BB
    5381  3C 1C 07 40 04          BBC $071C,#64,consult_go_start  ; rom_read?
    5386  22 3F 54 00             JSL $00543F       ; setup ROM read response

consult_go_start:
    538A  5C 37 54 00             JMP consult_rx_exit

; More commands while building the stream request list
consult_stream_check_more:
    538E  42 C9 0A                CMPB #$0A        ; active test command?
    5391  D0 0D                   BNE consult_stream_check_prev_cmd
    5393  AD 3C 07                LDA $073C        ; active_test_count
    5396  C9 05                   CMP #$05         ; max 5 concurrent active tests
    5398  B0 0F                   BCS consult_send_stop_ack
    539A  1C 1C 07 48             CLB $4807,#$1C   ; clear rom_read + reg_read
    539E  80 44                   BRA consult_stream_accept

consult_stream_check_prev_cmd:
    53A0  AD 3A 07                LDA $073A        ; previous cmd_byte
    53A3  F0 11                   BEQ consult_stream_no_prev
    53A5  C9 51                   CMP #$51         ; was prev cmd DTC read?
    53A7  F0 16                   BEQ consult_stream_validate

; Send stop ack ($FE) and reset: unknown/rejected command
consult_send_stop_ack:
    53A9  0C 1C 07 02             SEB $0207,#$1C   ; stop_req
    53AD  22 C7 54 00             JSL $0054C7       ; flush_uart
    53B1  42 A9 FE                LDB #$FE         ; stop ack byte = $FE
    53B4  80 64                   BRA consult_tx_echo

consult_stream_no_prev:
    53B6  42 C9 51                CMPB #$51        ; DTC read?
    53B9  D0 04                   BNE consult_stream_validate
    53BB  5C 3C 50 00             JMP consult_cmd_dtc_read

consult_stream_validate:
    53BF  AD 3B 07                LDA $073B        ; arg_count
    53C2  C9 28                   CMP #$28         ; max 40 register args
    53C4  B0 E3                   BCS consult_send_stop_ack  ; too many → reject
    53C6  42 C9 C9                CMPB #$C9        ; ROM read?
    53C9  D0 0B                   BNE consult_stream_check_5a
    53CB  2C 1C 07 08 D9          BBS $071C,#8,consult_send_stop_ack  ; can't mix 5A + C9
    53D0  0C 1C 07 40             SEB $4007,#$1C   ; set rom_read
    53D4  80 0E                   BRA consult_stream_accept

consult_stream_check_5a:
    53D6  42 C9 5A                CMPB #$5A        ; register read?
    53D9  D0 CE                   BNE consult_send_stop_ack  ; unknown → reject
    53DB  2C 1C 07 40 C9          BBS $071C,#64,consult_send_stop_ack  ; can't mix C9 + 5A
    53E0  0C 1C 07 08             SEB $0807,#$1C   ; set reg_read

consult_stream_accept:
    53E4  1C 1B 07 10             CLB $1007,#$1B   ; clear cmd_parsed
    53E8  0C 1B 07 0C             SEB $0C07,#$1B   ; set has_arg + got_init
    53EC  80 25                   BRA consult_clear_first_ff

; --- Active streaming: accept STOP or FF during data streaming ---
consult_stream_active:
    53EE  3C 1B 07 20 44          BBC $071B,#32,consult_rx_exit  ; not streaming? → exit
    53F3  2C C2 07 80 B1          BBS $07C2,#128,consult_send_stop_ack  ; framing error
    53F8  42 C9 FF                CMPB #$FF        ; re-init during stream?
    53FB  D0 04                   BNE consult_stream_check_stop_30
    53FD  5C DB 4F 00             JMP consult_cmd_init

consult_stream_check_stop_30:
    5401  42 C9 30                CMPB #$30        ; STOP during stream?
    5404  D0 A3                   BNE consult_send_stop_ack  ; anything else → reject
    5406  3C BC 07 04 04          BBC $07BC,#4,consult_stream_do_stop
    540B  0C 69 0F 10             SEB $100F,#$69   ; flag active test shutdown

consult_stream_do_stop:
    540F  5C F3 4F 00             JMP consult_cmd_stop

; --- Echo/TX path: send response byte back on UART1 ---
consult_clear_first_ff:
    5413  1C 1B 07 80             CLB $8007,#$1B   ; clear first_FF_seen

consult_echo_reply:
    5417  42 49 FF                EORB #$FF        ; B = ~rx_byte (complement echo)

consult_tx_echo:
    541A  2C 1C 07 10 04          BBS $071C,#16,consult_tx_start  ; already sending?
    541F  24 35 02 0D             BBS $35,#2,consult_tx_direct  ; UART TX ready?

consult_tx_start:
    5423  04 F0 02                SEB $02,#$F0     ; enable UART1 TX interrupt
    5426  0C 1C 07 20             SEB $2007,#$1C   ; set tx_ready
    542A  42 8D 38 07             STB $0738        ; queue byte for TX interrupt
    542E  80 07                   BRA consult_rx_exit

consult_tx_direct:
    5430  22 C7 54 00             JSL $0054C7       ; flush
    5434  42 85 32                STB $32          ; write directly to UART1 TX

consult_rx_exit:
